class ResponsiveLayoutScreen extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    final screenWidth = MediaQuery.of(context).size.width;

    return Scaffold(
      appBar: AppBar(title: Text('Responsive Demo')),
      body: Center(
        child: screenWidth < 600
            ? _buildNarrowLayout()
            : _buildWideLayout(),
      ),
    );
  }

